{
  "name": "opencode-plugin-statusline",
  "version": "0.1.0",
  "description": "OpenCode TUI plugin: context, prompt cache, live work and session cost status line in the prompt footer",
  "type": "module",
  "license": "MIT",
  "author": "Alexey Rehov <alexey.rehov@gmail.com>",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Zorato/opencode-plugin-statusline.git"
  },
  "bugs": {
    "url": "https://github.com/Zorato/opencode-plugin-statusline/issues"
  },
  "homepage": "https://github.com/Zorato/opencode-plugin-statusline#readme",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "statusline",
    "context",
    "prompt-cache",
    "cost"
  ],
  "files": [
    "index.ts",
    "tui.tsx"
  ],
  "scripts": {
    "typecheck": "tsc --noEmit"
  },
  "exports": {
    ".": "./index.ts",
    "./tui": "./tui.tsx"
  },
  "dependencies": {
    "@opencode/plugin": "latest"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.6.8",
    "@opentui/solid": ">=0.6.8",
    "solid-js": ">=1.9.0"
  },
  "devDependencies": {
    "@opencode/theme": "^2.1.4",
    "@types/node": "^24.0.0",
    "typescript": "^5.9.0"
  }
}
